1	import {
2	  openSync,
3	  closeSync,
4	  writeSync,
5	  fsyncSync,
6	  mkdirSync,
7	  readFileSync,
8	  writeFileSync,
9	  truncateSync,
10	  renameSync,
11	  rmSync,
12	  existsSync,
13	} from 'node:fs';
14	import path from 'node:path';
15	import { randomUUID } from 'node:crypto';
16	
17	const LOG_NAME = 'bus.jsonl';
18	const LOG_TMP_NAME = 'bus.log.tmp';
19	const SNAPSHOT_NAME = 'bus.snapshot.json';
20	const SNAPSHOT_TMP_NAME = 'bus.snapshot.tmp';
