22	/**
23	 * Validate that `value` survives a compact JSON.stringify unchanged.
24	 * JSON silently drops undefined / functions and turns non-finite numbers
25	 * into null; the spec rejects those along with BigInt and circular
26	 * references as TypeError.
27	 */
28	function assertJsonSafe(value, stack = new Set()) {
29	  if (typeof value === 'bigint') {
30	    throw new TypeError('record contains a BigInt');
31	  }
32	  if (typeof value === 'function') {
33	    throw new TypeError('record contains a function');
34	  }
35	  if (typeof value === 'undefined') {
36	    throw new TypeError('record contains undefined');
37	  }
38	  if (typeof value === 'number' && !Number.isFinite(value)) {
39	    throw new TypeError('record contains a non-finite number');
40	  }
41	  if (value !== null && typeof value === 'object') {
42	    // Unbox boxed primitives (e.g. new Number(NaN)) before recursing.
43	    if (value instanceof Number || value instanceof String || value instanceof Boolean) {
44	      assertJsonSafe(value.valueOf(), stack);
45	      return;
46	    }
47	    if (stack.has(value)) {
48	      throw new TypeError('record contains a circular reference');
49	    }
50	    stack.add(value);
51	    if (Array.isArray(value)) {
52	      for (const item of value) assertJsonSafe(item, stack);
53	    } else {
54	      for (const key of Object.keys(value)) assertJsonSafe(value[key], stack);
55	    }
56	    stack.delete(value);
57	  }
58	}
