60	/**
61	 * Split a jsonl buffer into parsed entries. `durable` is the offset just
62	 * past the final newline; anything beyond it is a torn trailing write.
63	 */
64	function parseLog(raw) {
65	  const entries = [];
66	  let start = 0;
67	  for (let i = 0; i < raw.length; i++) {
68	    if (raw[i] === 0x0a) {
69	      if (i > start) entries.push(JSON.parse(raw.toString('utf8', start, i)));
70	      start = i + 1;
71	    }
72	  }
73	  return { entries, durable: start };
74	}
