76	export function createBus({ path: dir, fsync = false } = {}) {
77	  if (typeof dir !== 'string' || dir.length === 0) {
78	    throw new TypeError('createBus: "path" must be a non-empty string');
79	  }
80	
81	  const logPath = path.join(dir, LOG_NAME);
82	  const logTmpPath = path.join(dir, LOG_TMP_NAME);
83	  const snapshotPath = path.join(dir, SNAPSHOT_NAME);
84	  const snapshotTmpPath = path.join(dir, SNAPSHOT_TMP_NAME);
85	
86	  let seq = 0; // seq of the last effective message
87	  let bytes = 0;
88	  let published = 0;
89	  let replayed = 0;
90	  // dedupKey -> { id, seq } for effective messages
91	  const dedup = new Map();
92	  // dedupKey -> { promise, resolve, reject } for first publish in flight
93	  const pending = new Map();
94	  // dedupKey -> { promise, resolve, reject } reserved by the first
95	  // in-flight batch carrying that key; lets later singles/batches share
96	  // the batch's first acknowledgement just like `pending` does for singles
97	  const groupPending = new Map();
98	  // consumer name -> position (seq of the last consumed message; 0 = none)
99	  const positions = new Map();
100	  // generation of the newest durable snapshot; 0 = no snapshot yet
101	  let snapshotGen = 0;
102	  // messages folded into the snapshot, served to replay/read after truncation
103	  let baseMessages = [];
104	
105	  // ---- synchronous recovery so stats() is correct the moment createBus returns
106	  mkdirSync(dir, { recursive: true });
107	
108	  // A leftover tmp file is a snapshot that crashed mid-write. The pre-compact
109	  // log is still intact, so the half snapshot carries no state: drop it.
110	  rmSync(snapshotTmpPath, { force: true });
111	  // Likewise a log tmp left behind when compact crashed before the rename:
112	  // the live log (if any) is still the source of truth.
113	  rmSync(logTmpPath, { force: true });
114	
115	  if (existsSync(snapshotPath)) {
116	    const snap = JSON.parse(readFileSync(snapshotPath, 'utf8'));
117	    snapshotGen = snap.gen;
118	    seq = snap.seq;
119	    bytes = snap.bytes;
120	    published = snap.published;
121	    replayed = snap.replayed;
122	    for (const [key, value] of snap.dedup) dedup.set(key, value);
123	    for (const [name, pos] of Object.entries(snap.positions)) positions.set(name, pos);
124	    baseMessages = snap.messages;
125	  }
126	
127	  const applyEntry = (entry) => {
128	    if (entry.t === 'm') {
129	      seq = entry.seq;
130	      bytes += entry.bytes;
131	      published += 1;
132	      if (typeof entry.d === 'string') {
133	        dedup.set(entry.d, { id: entry.id, seq: entry.seq });
134	      }
135	    } else if (entry.t === 's') {
136	      replayed += entry.n;
137	    } else if (entry.t === 'p') {
138	      positions.set(entry.name, entry.pos);
139	    }
140	  };
141	
142	  const markerLine = (gen) => JSON.stringify({ t: 'c', gen }) + '\n';
143	
144	  // Replay complete log lines and apply only the committed prefix.
145	  // A batch is bracketed by {t:'b',id} .. entries .. {t:'bk',id}: a begin
146	  // without its matching commit (crash mid-write, or overtaken by a newer
147	  // begin) is severed wholesale and none of its entries take effect.
148	  // Returns the byte offset just past the last committed line, so both a
149	  // torn trailing write and an uncommitted batch tail can be truncated.
150	  const recoverLog = (raw) => {
151	    let lineStart = 0;
152	    let committedEnd = 0;
153	    let group = null;
154	    for (let i = 0; i < raw.length; i++) {
155	      if (raw[i] !== 0x0a) continue;
156	      const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
157	      if (group !== null) {
158	        if (entry && entry.t === 'bk' && entry.id === group.id) {
159	          for (const e of group.entries) applyEntry(e);
160	          group = null;
161	          committedEnd = i + 1;
162	        } else if (entry && entry.t === 'b') {
163	          // The previous group never committed; start tracking the new one.
164	          group = { id: entry.id, entries: [] };
165	        } else if (entry) {
166	          group.entries.push(entry);
167	        }
168	      } else if (entry && entry.t === 'b') {
169	        group = { id: entry.id, entries: [] };
170	      } else {
171	        if (entry) applyEntry(entry);
172	        committedEnd = i + 1;
173	      }
174	      lineStart = i + 1;
175	    }
176	    return committedEnd;
177	  };
178	
179	  if (existsSync(logPath)) {
180	    const raw = readFileSync(logPath);
181	    const { entries } = parseLog(raw);
182	    if (snapshotGen > 0) {
183	      const first = entries[0];
184	      if (first && first.t === 'c' && first.gen === snapshotGen) {
185	        // Live post-compact log: the marker line applies as a no-op.
186	        const committedEnd = recoverLog(raw);
187	        if (committedEnd < raw.length) truncateSync(logPath, committedEnd);
188	      } else {
189	        // Crash between snapshot rename and log truncation (or between
190	        // truncation and marker write): every byte of this log is already
191	        // folded into the snapshot. Reset it to just the marker so the
192	        // state is unambiguous from here on.
193	        writeFileSync(logPath, markerLine(snapshotGen));
194	      }
195	    } else {
196	      const committedEnd = recoverLog(raw);
197	      if (committedEnd < raw.length) truncateSync(logPath, committedEnd);
198	    }
199	  } else if (snapshotGen > 0) {
200	    writeFileSync(logPath, markerLine(snapshotGen));
201	  }
202	
203	  // Reassigned by compact() when it closes/truncates/reopens the log.
204	  let fd = openSync(logPath, 'a');
205	
206	  let chain = Promise.resolve();
207	  let closed = false;
208	  // A failed append may leave a torn line; stop appending so later writes
209	  // cannot glue themselves onto it. The torn tail is truncated on reopen.
210	  let broken = false;
211	
212	  // All disk mutation by publish/replay/compact happens inside this serial
213	  // chain; writeSync keeps each append atomic with respect to the event loop
214	  // while still returning a Promise to callers.
215	  const enqueue = (job) => {
216	    const run = chain.then(job);
217	    // A failed job must not stall every later operation.
218	    chain = run.then(
219	      () => {},
220	      () => {},
221	    );
222	    return run;
223	  };
224	
225	  const writeLine = (entry) => {
226	    writeSync(fd, Buffer.from(JSON.stringify(entry) + '\n', 'utf8'));
227	    if (fsync) fsyncSync(fd);
228	  };
229	
230	  // Position writes are synchronous (register/advance/read are synchronous
231	  // methods) and order-independent against 'm'/'s' entries, so they append
232	  // directly rather than through the chain.
233	  const persistPosition = (name, pos) => {
234	    try {
235	      writeLine({ t: 'p', name, pos });
236	    } catch (err) {
237	      broken = true;
238	      throw err;
239	    }
240	  };
241	
242	  const assertOpen = () => {
243	    if (closed || broken) {
244	      throw new Error('bus is closed');
245	    }
246	  };
247	
248	  const assertName = (name) => {
249	    if (typeof name !== 'string' || name.length === 0) {
250	      throw new TypeError('consumer name must be a non-empty string');
251	    }
252	  };
253	
254	  // Messages with seq > pos, snapshot first then live log, ascending.
255	  const messagesAfter = (pos) => {
256	    const out = [];
257	    for (const m of baseMessages) {
258	      if (m.seq > pos) {
259	        // Snapshot messages are shared in-memory objects; hand out a copy so
260	        // callers cannot mutate replay/read results for later calls.
261	        out.push({ seq: m.seq, id: m.id, record: structuredClone(m.record) });
262	      }
263	    }
264	    const { entries } = parseLog(readFileSync(logPath));
265	    for (const entry of entries) {
266	      if (entry.t === 'm' && entry.seq > pos) {
267	        out.push({ seq: entry.seq, id: entry.id, record: entry.record });
268	      }
269	    }
270	    return out;
271	  };
272	
273	  const bus = {
274	    publish(record) {
275	      if (closed) {
276	        return Promise.reject(new Error('bus is closed'));
277	      }
278	      if (record === null || typeof record !== 'object' || Array.isArray(record)) {
279	        return Promise.reject(new TypeError('publish: record must be a JSON object'));
280	      }
281	      const dedupKey = record.dedupKey;
282	      if (dedupKey !== undefined && typeof dedupKey !== 'string') {
283	        return Promise.reject(new TypeError('publish: dedupKey must be a string'));
284	      }
285	      try {
286	        assertJsonSafe(record);
287	      } catch (err) {
288	        return Promise.reject(err);
289	      }
290	      const size = Buffer.byteLength(JSON.stringify(record), 'utf8');
291	
292	      // Duplicate of an effective message (possibly recovered from disk).
293	      if (dedupKey !== undefined) {
294	        const first = dedup.get(dedupKey);
295	        if (first) {
296	          return Promise.resolve({ id: first.id, seq: first.seq });
297	        }
298	        const inflight = pending.get(dedupKey);
299	        if (inflight) {
300	          return inflight.promise;
301	        }
302	        const inflightGroup = groupPending.get(dedupKey);
303	        if (inflightGroup) {
304	          return inflightGroup.promise;
305	        }
306	      }
307	
308	      // Reserve in-flight dedup at call time so concurrent resends of the
309	      // same order share the first result; FIFO enqueue assigns seq in
310	      // invocation order.
311	      let resolveResult;
312	      let rejectResult;
313	      const promise = new Promise((resolve, reject) => {
314	        resolveResult = resolve;
315	        rejectResult = reject;
316	      });
317	      if (dedupKey !== undefined) {
318	        pending.set(dedupKey, { promise, resolve: resolveResult, reject: rejectResult });
319	      }
320	
321	      enqueue(() => {
322	        if (closed || broken) {
323	          throw new Error('bus is closed');
324	        }
325	        const mySeq = seq + 1;
326	        const id = randomUUID();
327	        const entry = { t: 'm', seq: mySeq, id, bytes: size, record };
328	        if (dedupKey !== undefined) entry.d = dedupKey;
329	        try {
330	          // Durable before acknowledgement: state changes only after the
331	          // write (and optional fsync) succeeds.
332	          writeLine(entry);
333	        } catch (err) {
334	          broken = true;
335	          throw err;
336	        }
337	        seq = mySeq;
338	        bytes += size;
339	        published += 1;
340	        if (dedupKey !== undefined) {
341	          dedup.set(dedupKey, { id, seq: mySeq });
342	          pending.delete(dedupKey);
343	          resolveResult({ id, seq: mySeq });
344	        }
345	        return { id, seq: mySeq };
346	      }).then(
347	        (ack) => {
348	          if (dedupKey === undefined) resolveResult(ack);
349	        },
350	        (err) => {
351	          if (dedupKey !== undefined) pending.delete(dedupKey);
352	          rejectResult(err);
353	        },
354	      );
355	
356	      return promise;
357	    },
358	
359	    publishBatch(records) {
360	      // Spec: a non-array argument is always a synchronous TypeError.
361	      if (!Array.isArray(records)) {
362	        throw new TypeError('publishBatch: records must be an array');
363	      }
364	      if (closed) {
365	        return Promise.reject(new Error('bus is closed'));
366	      }
367	
368	      // Validate and serialize every record up front. Any single bad shape
369	      // (or value JSON cannot carry) rejects the whole group before the
370	      // serial chain is touched: seq/bytes/published/dedup/positions stay
371	      // exactly as they were.
372	      const prepared = [];
373	      try {
374	        for (const record of records) {
375	          if (record === null || typeof record !== 'object' || Array.isArray(record)) {
376	            throw new TypeError('publishBatch: record must be a JSON object');
377	          }
378	          const dedupKey = record.dedupKey;
379	          if (dedupKey !== undefined && typeof dedupKey !== 'string') {
380	            throw new TypeError('publishBatch: dedupKey must be a string');
381	          }
382	          assertJsonSafe(record);
383	          // Serialize exactly once per record: the byte count used for
384	          // stats and the bytes actually appended must be the same string.
385	          const recordJson = JSON.stringify(record);
386	          prepared.push({
387	            dedupKey,
388	            recordJson,
389	            size: Buffer.byteLength(recordJson, 'utf8'),
390	          });
391	        }
392	      } catch (err) {
393	        return Promise.reject(err);
394	      }
395	      if (prepared.length === 0) {
396	        return Promise.resolve([]);
397	      }
398	
399	      // Reserve the group's first-occurrence keys at call time, mirroring
400	      // publish()'s `pending`: a concurrent single or batch carrying the
401	      // same key shares this group's first acknowledgement. Keys already in
402	      // history or reserved by an earlier in-flight op are left alone.
403	      const reservations = new Map();
404	      for (const item of prepared) {
405	        const key = item.dedupKey;
406	        if (key === undefined) continue;
407	        if (dedup.has(key) || pending.has(key) || groupPending.has(key)) continue;
408	        if (reservations.has(key)) continue;
409	        let resolveResult;
410	        let rejectResult;
411	        const promise = new Promise((resolve, reject) => {
412	          resolveResult = resolve;
413	          rejectResult = reject;
414	        });
415	        // This promise is a coordination primitive: callers that race the
416	        // reservation attach their own branch (publish returns it). A group
417	        // with no such racer would otherwise leave the rejection unhandled
418	        // when the bus closes before the job runs. The noop branch only
419	        // handles the event for the process; racers still observe it.
420	        promise.catch(() => {});
421	        const reservation = { promise, resolve: resolveResult, reject: rejectResult };
422	        reservations.set(key, reservation);
423	        groupPending.set(key, reservation);
424	      }
425	
426	      return enqueue(() => {
427	        if (closed || broken) {
428	          throw new Error('bus is closed');
429	        }
430	
431	        // Resolve the whole plan against durable state inside the serial
432	        // job, so groups queued behind earlier publishes/batches observe
433	        // their committed dedup keys.
434	        const gid = randomUUID();
435	        let nextSeq = seq;
436	        const owned = new Map(); // key -> first acknowledgement within group
437	        const keyAcks = new Map(); // every dedup key's resolved acknowledgement
438	        const planned = prepared.map((item) => {
439	          const key = item.dedupKey;
440	          if (key !== undefined) {
441	            const hist = dedup.get(key);
442	            if (hist) {
443	              const reuse = { id: hist.id, seq: hist.seq };
444	              keyAcks.set(key, reuse);
445	              return { reuse };
446	            }
447	            const earlier = owned.get(key);
448	            if (earlier) {
449	              return { reuse: earlier };
450	            }
451	          }
452	          nextSeq += 1;
453	          const id = randomUUID();
454	          const ack = { id, seq: nextSeq };
455	          if (key !== undefined) {
456	            owned.set(key, ack);
457	            keyAcks.set(key, ack);
458	          }
459	          // Splice the already-serialized record into the line so the
460	          // persisted bytes are exactly what `size` counted.
461	          let line = `{"t":"m","seq":${nextSeq},"id":${JSON.stringify(id)},"bytes":${item.size}`;
462	          if (key !== undefined) line += `,"d":${JSON.stringify(key)}`;
463	          line += `,"record":${item.recordJson}}\n`;
464	          return { effective: { ack, line, size: item.size, key } };
465	        });
466	
467	        // One begin-bracket, the group's new messages, one commit-bracket.
468	        // Recovery applies the bracketed entries only when the commit is
469	        // present, so a crash leaves no trace of the group.
470	        const buffers = [Buffer.from(JSON.stringify({ t: 'b', id: gid }) + '\n', 'utf8')];
471	        for (const part of planned) {
472	          if (part.effective) {
473	            buffers.push(Buffer.from(part.effective.line, 'utf8'));
474	          }
475	        }
476	        buffers.push(Buffer.from(JSON.stringify({ t: 'bk', id: gid }) + '\n', 'utf8'));
477	
478	        try {
479	          // Coalesce in small chunks (bounds peak memory for huge groups)
480	          // and loop over partial writes. Single-buffer writeSync is used
481	          // rather than writev so the append behaves identically on Windows.
482	          // Everything here is synchronous inside this job, so no position
483	          // write can interleave. The begin/commit brackets keep the group
484	          // atomic across a crash even if a partial write occurs.
485	          const CHUNK = 256;
486	          for (let i = 0; i < buffers.length; i += CHUNK) {
487	            const chunk = Buffer.concat(buffers.slice(i, i + CHUNK));
488	            let off = 0;
489	            while (off < chunk.length) {
490	              const written = writeSync(fd, chunk, off, chunk.length - off);
491	              if (!Number.isInteger(written) || written <= 0) {
492	                throw new Error('publishBatch: write made no progress, group is not durable');
493	              }
494	              off += written;
495	            }
496	          }
497	          if (fsync) fsyncSync(fd);
498	        } catch (err) {
499	          // Nothing is applied in memory; the uncommitted bracket is
500	          // severed on reopen. Stop the bus so later writes cannot glue
501	          // themselves onto the partial group. Reservations are reclaimed
502	          // by the outer catch below.
503	          broken = true;
504	          throw err;
505	        }
506	
507	        // Durable first, state after.
508	        for (const part of planned) {
509	          if (!part.effective) continue;
510	          const { ack, size, key } = part.effective;
511	          seq = ack.seq;
512	          bytes += size;
513	          published += 1;
514	          if (key !== undefined) dedup.set(key, { id: ack.id, seq: ack.seq });
515	        }
516	
517	        const acks = planned.map((part) =>
518	          part.reuse ? { id: part.reuse.id, seq: part.reuse.seq } : { id: part.effective.ack.id, seq: part.effective.ack.seq },
519	        );
520	        for (const [key, reservation] of reservations) {
521	          groupPending.delete(key);
522	          reservation.resolve(keyAcks.get(key));
523	        }
524	        return acks;
525	      }).catch((err) => {
526	        // Covers write failure inside the job and rejection before the job
527	        // body (closed/broken bus): release any reservation still pointing
528	        // at this failed group.
529	        for (const [key, reservation] of reservations) {
530	          if (groupPending.get(key) === reservation) groupPending.delete(key);
531	          reservation.reject(err);
532	        }
533	        throw err;
534	      });
535	    },
536	
537	    replay(from = 0) {
538	      if (closed) {
539	        return Promise.reject(new Error('bus is closed'));
540	      }
541	      if (typeof from !== 'number' || !Number.isInteger(from) || from < 0) {
542	        return Promise.reject(new RangeError('replay: from must be a non-negative integer'));
543	      }
544	
545	      return enqueue(() => {
546	        if (closed || broken) {
547	          throw new Error('bus is closed');
548	        }
549	        // replay(from) is inclusive of from; messagesAfter takes an
550	        // exclusive lower bound.
551	        const out = messagesAfter(from - 1);
552	        const n = out.length;
553	        if (n > 0) {
554	          try {
555	            writeLine({ t: 's', n });
556	          } catch (err) {
557	            broken = true;
558	            throw err;
559	          }
560	          replayed += n;
561	        }
562	        return out;
563	      });
564	    },
565	
566	    register(name) {
567	      assertOpen();
568	      assertName(name);
569	      const current = positions.get(name);
570	      // Re-registering an existing name must not reset its position.
571	      if (current !== undefined) {
572	        return current;
573	      }
574	      persistPosition(name, 0);
575	      positions.set(name, 0);
576	      return 0;
577	    },
578	
579	    advance(name, to) {
580	      assertOpen();
581	      assertName(name);
582	      if (typeof to !== 'number' || !Number.isInteger(to) || to < 0) {
583	        throw new RangeError('advance: position must be a non-negative integer');
584	      }
585	      const current = positions.get(name);
586	      if (current !== undefined) {
587	        if (to < current) {
588	          throw new RangeError('advance: position cannot move backwards');
589	        }
590	        if (to === current) {
591	          return current;
592	        }
593	      }
594	      // An unknown name is auto-registered, same as register() first.
595	      persistPosition(name, to);
596	      positions.set(name, to);
597	      return to;
598	    },
599	
600	    read(name) {
601	      assertOpen();
602	      assertName(name);
603	      let pos = positions.get(name);
604	      if (pos === undefined) {
605	        pos = 0;
606	        persistPosition(name, pos);
607	        positions.set(name, pos);
608	      }
609	      // read never moves the position; advance() is how consumption lands.
610	      return messagesAfter(pos);
611	    },
612	
613	    compact() {
614	      if (closed) {
615	        return Promise.reject(new Error('bus is closed'));
616	      }
617	      return enqueue(() => {
618	        if (closed || broken) {
619	          throw new Error('bus is closed');
620	        }
621	        const { entries } = parseLog(readFileSync(logPath));
622	        const messages = baseMessages.slice();
623	        for (const entry of entries) {
624	          if (entry.t === 'm') {
625	            messages.push({ seq: entry.seq, id: entry.id, record: entry.record });
626	          }
627	        }
628	        const gen = snapshotGen + 1;
629	        const snapshot = {
630	          v: 1,
631	          gen,
632	          seq,
633	          bytes,
634	          published,
635	          replayed,
636	          positions: Object.fromEntries(positions),
637	          dedup: Array.from(dedup.entries()),
638	          messages,
639	        };
640	        // The snapshot is durable (fsync + atomic rename) before the log is
641	        // truncated, so a crash anywhere leaves either the intact old log
642	        // (half tmp snapshot, discarded on reopen) or the new marker-led
643	        // log — never something in between.
644	        const tmpFd = openSync(snapshotTmpPath, 'w');
645	        try {
646	          writeSync(tmpFd, Buffer.from(JSON.stringify(snapshot) + '\n', 'utf8'));
647	          fsyncSync(tmpFd);
648	        } finally {
649	          closeSync(tmpFd);
650	        }
651	        renameSync(snapshotTmpPath, snapshotPath);
652	        // Best-effort durability for the rename itself. If syncing the
653	        // directory fails (some platforms/filesystems expose no directory
654	        // fsync) leaving the old log in place is still safe: every byte of
655	        // it is covered by the new snapshot, so recovery folds it
656	        // harmlessly on reopen.
657	        let dirSynced = false;
658	        try {
659	          const dirFd = openSync(dir, 'r');
660	          try {
661	            fsyncSync(dirFd);
662	            dirSynced = true;
663	          } finally {
664	            closeSync(dirFd);
665	          }
666	        } catch {
667	          // Directory sync unavailable: the replacement below remains
668	          // crash-safe via the snapshot-covered old log.
669	        }
670	
671	        // Replacing the log must work on Windows: ftruncate() of an open
672	        // append handle does not shrink the file there. Close the handle,
673	        // write a fresh marker-only log to a temp name, fsync it, then
674	        // atomically rename it over the old one (libuv replaces the target)
675	        // and reopen. The whole swap is one synchronous segment, so no
676	        // reader can observe an intermediate state.
677	        closeSync(fd);
678	        let replaced = false;
679	        try {
680	          const newFd = openSync(logTmpPath, 'w');
681	          try {
682	            writeSync(newFd, Buffer.from(markerLine(gen), 'utf8'));
683	            fsyncSync(newFd);
684	          } finally {
685	            closeSync(newFd);
686	          }
687	          renameSync(logTmpPath, logPath);
688	          replaced = true;
689	          // Best-effort durability of the directory entry (may be
690	          // unavailable on Windows / some filesystems); a crash here
691	          // recovers to either the intact old log or the new one — both
692	          // fully covered by the snapshot above.
693	          if (dirSynced) {
694	            const dirFd2 = openSync(dir, 'r');
695	            try {
696	              fsyncSync(dirFd2);
697	            } finally {
698	              closeSync(dirFd2);
699	            }
700	          }
701	          fd = openSync(logPath, 'a');
702	          fsyncSync(fd);
703	        } catch (err) {
704	          if (!replaced) {
705	            // New log never landed; the old log is fully covered by the new
706	            // snapshot regardless. Reopen it so close() still works, but
707	            // refuse further writes on this instance.
708	            try {
709	              fd = openSync(logPath, 'a');
710	            } catch {
711	              // Nothing usable: leave fd closed; every later op throws.
712	            }
713	          }
714	          broken = true;
715	          throw err;
716	        }
717	        snapshotGen = gen;
718	        baseMessages = messages;
719	      });
720	    },
721	
722	    stats() {
723	      return { seq, bytes, published, replayed };
724	    },
725	
726	    close() {
727	      if (closed) {
728	        return Promise.resolve();
729	      }
730	      closed = true;
731	      // Reject any publish whose dedup reservation is still queued.
732	      for (const [key, p] of pending) {
733	        p.reject(new Error('bus is closed'));
734	        pending.delete(key);
735	      }
736	      // And every reservation held by a batch still waiting in the chain.
737	      for (const [key, g] of groupPending) {
738	        g.reject(new Error('bus is closed'));
739	        groupPending.delete(key);
740	      }
