742	        // A failed compact may have left the append handle unusable; close
743	        // must stay idempotent and never reject.
744	        try {
745	          if (fsync) fsyncSync(fd);
746	        } catch {
747	          // Ignore: the handle may already be closed.
748	        }
749	        try {
750	          closeSync(fd);
751	        } catch {
752	          // Already closed by the compact failure path.
753	        }
754	      });
755	    },
756	  };
757	
758	  return bus;
759	}
