  assert.deepEqual(await reopened.replay(0), []);
  const acks = await reopened.publishBatch([{ a: 2 }, { a: 3 }]);
  assert.deepEqual(
    acks.map((a) => a.seq),
    [1, 2],
  );
  await reopened.close();
});

